from pathlib import Path
import base64,re
from PIL import Image
root=Path.cwd();out=root/'reports';shots=out/'guide-a4-captures'
font=base64.b64encode((root/'public/assets/fonts/Pretendard-Medium.woff2').read_bytes()).decode()
def photo(file,rect,caption):
 p=shots/file;x,y,w,h=rect;raw_w,raw_h=Image.open(p).size
 assert x+w<=raw_w and y+h<=raw_h,(file,rect,(raw_w,raw_h))
 data=base64.b64encode(p.read_bytes()).decode();mime='image/png' if p.read_bytes()[:4]==b'\x89PNG' else 'image/jpeg'
 return f'<figure><button class="shot" aria-label="{caption} 확대" style="aspect-ratio:{w}/{h}"><img src="data:{mime};base64,{data}" alt="{caption}" style="width:{raw_w/w*100:.5f}%;left:{-x/w*100:.5f}%;top:{-y/h*100:.5f}%"></button><figcaption>{caption} · 선택 시 원본 화면 확대</figcaption></figure>'
def head(n,title,desc):return f'<header><p class="kicker">SHOES RESEARCH · MLB / DISCOVERY · USER GUIDE</p><div class="heading"><h1>{title}</h1><span>0{n} / 03</span></div><p class="intro">{desc}</p></header>'
def foot(n):return f'<footer><span>내부용 · 동일 배포 코드와 실제 자료의 검증 화면 · 2026.11.03</span><span>A4 세로 · {n} / 3</span></footer>'
def item(title,text):return f'<div><b>{title}</b><span>{text}</span></div>'
p1=head(1,'상품 탐색과 시장 신호 비교','이 사이트의 장점 · 상품·쇼·시장 신호를 모아 자료 탐색부터 MLB 기획안까지 한곳에서 연결')
p1+='<div class="flow">조사 동선 단축 · 출처별 탐색 → 공통 신호 확인 → MLB 적용안 → 제안서 제작</div>'
p1+='<nav class="menu-map"><b>상품 탐색</b> 전체 · 브랜드 공식 상품 · SNS 인기 신상 · 리테일 상품 · 뉴스레터<br><b>트렌드 리서치</b> CATWALK · 데이터 분석 · Forecast · 업무 브리프 · 레퍼런스 보드</nav>'
p1+='<section><h2><em>01</em>상품·브랜드·컬러 탐색</h2>'+photo('01-products.jpg',(305,310,925,350),'상품 카드 · 컬러칩 · 원문 연결')
p1+='<div class="notes two">'+item('출처와 필터 선택','공식·SNS·리테일·뉴스레터 선택 후 LUX·SPORTS·CASUAL, 브랜드, 품목, 검색어로 범위 설정')+item('스타일·변형 비교','SHOES TREND KEYWORD 1–15위와 선정 기준 확인 · 같은 모델의 컬러칩 선택으로 사진·컬러 비교')+item('저장과 상세 확인','별표로 저장함 등록 · 상품명·사진 선택으로 상세 확인 · 원문 연결 및 사진 JPG 저장')+item('선택 자료 활용','현재 페이지·개별 상품 선택 후 보드 담기 · CSV·XLSX 내보내기 · 정렬 및 필터 초기화 활용')+'</div></section>'
p1+='<section><h2><em>02</em>데이터 분석과 MLB 적용안 확인</h2>'+photo('02-analysis.jpg',(320,632,1000,290),'주간 공통 신호의 상품·런웨이 레퍼런스')
p1+='<div class="notes two">'+item('주간 핵심 인사이트','주목할 변화 → 공식·랭킹·런웨이·Forecast 근거 → MLB 적용 아이템의 순서로 확인')+item('랭킹·가격 비교','무신사·29CM·SSENSE 1–15위 확인 · 브랜드별 중앙값 오름차순과 MLB 기준선·차액·최저/최고 가격 비교')+'</div><p class="callout">랭킹은 스토어 원문 순위 기준 · 판매수량과 구분 · 이전 시즌 자료는 상단 Retail Archive 연결</p></section>'+foot(1)
p2=head(2,'런웨이·Forecast와 시즌 제안','이 사이트의 장점 · 쇼 사진·시즌 예측·기존 제안의 연결을 통한 근거 중심의 MLB 아이템 기획')
p2+='<section><h2><em>03</em>CATWALK 레퍼런스 수집</h2>'+photo('03-catwalk.jpg',(62,534,990,360),'런웨이 사진 · 브랜드·시즌 정보 · 보드 담기')
p2+='<div class="notes two">'+item('컬렉션과 쇼 탐색','전체·런웨이·Fashion Feed 구분 · 시즌·도시·쇼 검색과 필터 선택 · 전체에서는 런웨이 우선 표시')+item('사진 열람과 수집','사진 선택으로 크게 보기 · 개별 JPG·선택 ZIP 저장 · 체크박스와 Shift로 여러 장 선택 후 보드 담기')+'</div><p class="callout">사진별 실제 촬영 시즌·출처 보존 · Fashion Feed 설명은 원문 해시태그 기준</p></section>'
p2+='<section><h2><em>04</em>Forecast의 다음 시즌 방향 확인</h2>'+photo('04-forecast.jpg',(64,576,1160,360),'시즌별 스니커즈 레포트 카드')
p2+='<div class="notes two">'+item('시즌·레포트 선택','27SS·27AW(FW)·28SS 탭에서 스니커즈 레포트 선택 · 페이지 이동과 고화질 본문 확인 · WGSN 원문 연결')+item('시즌 키워드 활용','Key Silhouettes의 Fashion silhouette·Core updates 키워드 확인 · 매년 1월·7월 기준 시즌 창 자동 전환')+'</div></section>'
p2+='<section class="brief-box"><h2><em>05</em>업무 브리프의 시즌 제안 활용</h2><p>27SS·27FW·28SS별 6개, 총 18개 MLB 스니커즈 제안 확인 · 트렌드명·스타일 태그·공식/쇼 레퍼런스·인사이트·디자인 전략·출처 확인</p><p><b>편집 시작 경로</b> · 제안 카드의 ‘보드로 편집 ＋’ 또는 레퍼런스 보드의 ‘시즌 제안서 가져오기’ 선택 → 사진 6장·출처·인사이트를 포함한 독립 편집 보드 생성</p><p class="muted">원본 제안서 보존 · 목표가는 기획 가설로 구분 · 기존 제안서·시즌 요약의 고화질 PNG 저장 지원</p></section>'+foot(2)
p3=head(3,'레퍼런스 보드 제작과 내보내기','이 사이트의 편리함 · 사진·출처 자동 저장과 6장 자동 배치를 통한 제안서 조립 작업 절감')
p3+='<section><h2><em>06</em>프로젝트 생성과 사진·메모 편집</h2>'+photo('05-board.jpg',(514,315,1314,540),'제안서 미리보기와 프로젝트·시즌·태그 편집')
p3+='<ol class="steps"><li><b>새 보드 생성</b> · ‘＋ 새 보드’에서 시즌·프로젝트명 입력</li><li><b>사진 수집</b> · 상품·쇼의 ‘보드에 담기’로 프로젝트 선택</li><li><b>6장 자동 배치</b> · 추가 사진은 다음 페이지로 자동 분할</li><li><b>메모·순서 편집</b> · 사진 메모 입력, 드래그·↑↓로 순서 변경</li><li><b>태그·제안 편집</b> · 프로젝트명 기반 태그 추천과 직접 수정</li><li><b>적용안 정리</b> · 제목·인사이트·MLB 적용안·기획 메모 입력</li></ol><p class="callout">사진 메모는 제품명 위 배치 · 수동 태그는 프로젝트명 변경 후에도 유지 · ‘추천 다시 적용’으로 자동 추천 재적용</p></section>'
p3+='<section><h2><em>07</em>신발 크롭·확대와 결과 저장</h2>'+photo('06-crop.jpg',(355,280,1190,400),'원본의 크롭 범위와 확대 결과 비교')
p3+='<div class="notes two">'+item('사진별 크롭 조정','사진의 ‘크롭·확대’ 선택 → 왼쪽 범위 드래그 또는 확대·가로/세로 위치 조절 → ‘이 사진에 적용’ 선택')+item('자동·원본 전환','‘신발 자동 클로즈업’으로 재설정 · ‘저장된 원본 전체’로 복귀 · 복잡한 쇼 사진의 수동 범위 검토')+item('제안서 내보내기','PNG 4800×2700 또는 PDF 360dpi 선택 · 여러 페이지 PNG는 ZIP 저장 · PDF의 원문 출처 링크 유지')+item('보관·삭제·복원','프로젝트 복제·보관 및 보관함에서 복원 · 프로젝트 체크 후 선택 삭제 · 휴지통에서 삭제 취소·복원')+'</div></section>'
p3+='<p class="storage"><b>자동 저장과 이동</b> · 현재 브라우저에 사진·출처·메모 자동 저장 · 다른 브라우저로 이동 시 ‘사진 포함 백업’ 저장 후 ‘백업 가져오기’ 사용 · 다른 탭의 동시 수정 충돌 시 백업 우선 저장</p>'+foot(3)
css='''*{box-sizing:border-box}body{margin:0;background:#e9eef0;color:#243e4b;font-family:Pretendard,sans-serif;font-weight:500;font-synthesis:none}button,a{font:inherit}b{font-weight:500;color:#294d5b}h1,h2,p,figure{margin:0}h1{font-size:25px;letter-spacing:-.055em;line-height:1.4;font-weight:500}h2{font-size:17px;font-weight:500;letter-spacing:-.03em;margin-bottom:8px;line-height:1.35}h2 em{font-size:12px;color:#699c8a;letter-spacing:.03em;font-style:normal;margin-right:8px}.page{width:190mm;height:277mm;margin:22px auto;padding:0;display:flex;flex-direction:column;gap:10px;background:white;box-shadow:0 8px 28px #1b3d4914;outline:24px solid white}.kicker{font-size:9px;letter-spacing:.13em;color:#6e9185;margin-bottom:6px}.heading{display:flex;justify-content:space-between;align-items:center;gap:14px}.heading>span{font-size:11px;color:#729183;white-space:nowrap}.intro{font-size:12px;color:#6c808b;line-height:1.65;margin-top:5px}.flow{font-size:12px;background:#eef5f1;padding:8px 11px;color:#3e7463;border-radius:5px}.menu-map{font-size:11px;color:#6f818a;line-height:1.85}.menu-map b{margin-right:8px}.shot{display:block;position:relative;width:100%;padding:0;border:1px solid #d9e3e8;border-radius:6px;background:#f5f8f9;overflow:hidden;cursor:zoom-in}.shot img{position:absolute;max-width:none;height:auto;display:block}figcaption{font-size:9px;color:#82949b;line-height:1.5;margin-top:4px}.notes{display:grid;gap:7px 18px;margin-top:8px}.two{grid-template-columns:1fr 1fr}.notes>div{font-size:12px;line-height:1.7;word-break:keep-all}.notes b{display:block;color:#315c67}.notes span{color:#5c7380}.callout{font-size:10px;line-height:1.7;color:#527d70;background:#f0f6f2;padding:6px 9px;border-radius:5px;margin-top:8px}.brief-box{background:#f2f6f7;border:1px solid #e1e9eb;border-radius:7px;padding:12px}.brief-box p{font-size:12px;line-height:1.8;word-break:keep-all;margin-top:6px}.muted{font-size:10px!important;color:#728891}.steps{display:grid;grid-template-columns:1fr 1fr;gap:5px 22px;margin:8px 0 0;padding-left:18px;font-size:11px;line-height:1.7;color:#5b7480}.steps li::marker{color:#6c9688}.storage{font-size:10px;line-height:1.8;background:#edf5f0;border-left:3px solid #91b6a6;padding:9px 11px;color:#537565}footer{margin-top:auto;padding-top:8px;border-top:1px solid #e0e8eb;display:flex;justify-content:space-between;gap:10px;color:#8b9ca4;font-size:8px;line-height:1.5}.tools{width:190mm;max-width:94vw;display:flex;gap:10px;margin:22px auto 38px;justify-content:flex-end;align-items:center}.tools a,.tools button{border:1px solid #c6d8d0;background:white;border-radius:6px;padding:10px 14px;text-decoration:none;color:#437462;font-size:12px;cursor:pointer}.tools span{margin-right:auto;font-size:11px;color:#718992}dialog{width:96vw;max-width:1920px;border:0;border-radius:8px;background:#eff3f5;padding:12px;max-height:95vh;overflow:auto}dialog::backdrop{background:#142c43b8}dialog button{display:block;margin-left:auto;margin-bottom:10px;padding:8px 15px;border:1px solid #cbdbe2;border-radius:6px;background:white;cursor:pointer}dialog img{display:block;width:100%;height:auto}button:focus-visible,a:focus-visible{outline:2px solid #3c7c67;outline-offset:3px}@media(max-width:760px){.page{width:calc(100% - 32px);height:auto;min-height:0;padding:16px;outline:0;margin:18px auto;gap:13px}.notes.two,.steps{grid-template-columns:1fr}.notes>div{font-size:13px}.steps{font-size:12px}h1{font-size:23px}footer{margin-top:12px;flex-wrap:wrap}.tools{justify-content:flex-start;flex-wrap:wrap}.tools span{width:100%}}@page{size:A4 portrait;margin:10mm}@media print{body{background:white}.page{width:190mm;height:277mm;min-height:0;padding:0;margin:0;outline:0;box-shadow:none;break-after:page;gap:10px}.page:last-of-type{break-after:auto}.notes.two,.steps{grid-template-columns:1fr 1fr}.notes>div{font-size:12px}.steps{font-size:11px}h1{font-size:25px}footer{margin-top:auto;flex-wrap:nowrap}.tools,dialog{display:none!important}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
css+="#page-2{gap:7px}#page-3{gap:6px}"
css+=".section-route{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}.section-route h2{margin:0;flex-shrink:0}.tab-path{font-size:10px;line-height:1.6;color:#315c83;background:#eaf2fa;border:1px solid #d6e4f2;border-radius:5px;padding:4px 7px;max-width:68%;word-break:keep-all}.intro{color:#417663}.tools{position:sticky;top:0;z-index:2;background:#e9eef0ee;padding:10px 0;margin-top:8px;margin-bottom:24px}.tools .pdf-download{background:#3c7561;color:white;border-color:#3c7561}.tools .pdf-download:hover{background:#2e604e}@media(max-width:760px){.section-route{align-items:flex-start;flex-direction:column;gap:5px}.tab-path{max-width:100%}.tools{position:static}.tools a,.tools button{font-size:11px;padding:8px 10px}}@media print{.section-route{flex-direction:row;align-items:center;gap:8px}.tab-path{max-width:68%}.tools{display:none!important}}"

doc='<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SHOES RESEARCH · A4 세로 3페이지 사용설명서</title><style>@font-face{font-family:Pretendard;src:url(data:font/woff2;base64,'+font+') format("woff2");font-weight:500}'+css+'</style><div class="tools"><span>A4 세로 · 총 3페이지 · 화면 선택 시 확대</span><a href="https://shoes-update-internal.pages.dev/" target="_blank" rel="noopener">사이트 연결 ↗</a><a class="pdf-download" id="guide-pdf-download" href="./shoes-user-guide.pdf" download="SHOES-사용설명서-A4-3페이지.pdf">PDF 다운로드 ↓</a><button id="print">인쇄</button></div>'+''.join(f'<main class="page" id="page-{i+1}">{p}</main>' for i,p in enumerate([p1,p2,p3]))+'<dialog id="zoom"><button id="close">닫기 ×</button><img id="large" alt="선택 화면 원본 확대"></dialog><script>const d=document.querySelector("#zoom");document.querySelectorAll(".shot").forEach(b=>b.onclick=()=>{document.querySelector("#large").src=b.querySelector("img").src;d.showModal()});document.querySelector("#close").onclick=()=>d.close();document.querySelector("#print").onclick=()=>window.print();</script></html>'

routes={
 '01':'누를 탭 · 전체 / 브랜드 공식 상품 / SNS 인기 신상 / 리테일 상품 / 뉴스레터',
 '02':'누를 탭 · 데이터 분석',
 '03':'누를 탭 · CATWALK',
 '04':'누를 탭 · Forecast → 시즌 → 레포트',
 '05':'누를 탭 · 업무 브리프 → 시즌 → 보드로 편집 ＋',
 '06':'누를 탭 · 레퍼런스 보드 → ＋ 새 보드',
 '07':'누를 탭 · 레퍼런스 보드 → 사진 → 크롭·확대'
}
doc=re.sub(r'<h2><em>(\d+)</em>(.*?)</h2>',lambda m:'<div class="section-route">'+m.group(0)+'<span class="tab-path">'+routes[m.group(1)]+'</span></div>',doc)
assert doc.count('class="tab-path"')==7
(out/'shoes-user-guide.html').write_text(doc,encoding='utf-8');print('A4 portrait guide written:',len(doc))
